        /// <summary>Returns an inline SVG for the named icon (falls back to a plain circle for unknown names).</summary>
        public static IHtmlString Svg(string name, int size = 16, string cssClass = null)
        {
            string d;
            if (name == null || !paths.TryGetValue(name, out d))
                d = "M8 3a5 5 0 1 0 0 10A5 5 0 0 0 8 3";
            return new HtmlString(string.Format(
                "<svg class=\"ico{0}\" width=\"{1}\" height=\"{1}\" viewBox=\"0 0 16 16\" fill=\"currentColor\" aria-hidden=\"true\" focusable=\"false\"><path d=\"{2}\"/></svg>",
                cssClass == null ? "" : " " + cssClass, size, d));
        }

        public static IEnumerable<string> Names { get { return paths.Keys; } }
